"use client";

import { useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { Activity as ActivityIcon, AlertTriangle, BarChart3, Bell, BrainCircuit, Building2, CalendarClock, ChartNoAxesCombined, CheckCircle2, CircleAlert, Clock3, FileText, GitBranch, KeyRound, LayoutDashboard, LockKeyhole, Mail, Phone, PlugZap, Radio, RefreshCw, Route, Search, ShieldAlert, ShieldCheck, TimerReset, UserRound, UsersRound, Waves, type LucideIcon } from "lucide-react";
import { superAdminApi, SuperAdminApiError, type CompanyDetail, type SuperAdminActivity, type SuperAdminApi, type SuperAdminCompany, type SuperAdminConfiguration, type SuperAdminReferral, type LegacySuperAdminData, type SuperAdminRegistryEntry, type SuperAdminAuditLog } from "@/lib/super-admin-api";
