  const filtered = companies.filter(item => (filter === "All" || (filter === "Active" ? ["Approved", "TrialActive", "PaidActive"].includes(item.status) : filter === "Pending" ? item.status === "SignupPending" : filter === "Rejected" ? item.status === "SignupRejected" : item.status === "Suspended")) && `${item.name} ${item.signupEmail}`.toLowerCase().includes(query.toLowerCase()));
