  async function paid(id: string, renew: boolean) { await onAction(() => renew ? api.renewAnnual(id, { pipelineKmLimit: Number(km), namedUserLimit: Number(users) }) : api.activateAnnual(id, { pipelineKmLimit: Number(km), namedUserLimit: Number(users) })); setDetail(await api.getCompany(id)); }
  const activeDetail = detail ?? (selected ? details[selected.id] : undefined);
