function ClocksLegacy({ companies, details, legacy }: { companies: SuperAdminCompany[]; details: Record<string, CompanyDetail>; legacy: LegacySuperAdminData | null }) { const remaining = (date: string) => Math.max(0, Math.ceil((new Date(date).getTime() - Date.now()) / 86400000)); return <Card title="Trial and 365-day clocks"><p className="mb-4 text-xs text-slate-500">Trial and annual subscription periods are displayed separately from verified records.</p><div className="space-y-3 text-sm">{!companies.length ? <div className="rounded-lg border border-[#c8dfe1] bg-[#f3f7f8] p-4 text-sm text-[#155e64]">No verified trial or annual subscription records are available until database activation.</div> : null}{companies.map(item => { const detail = details[item.id]; const subscription = detail?.subscriptions.find(record => record.status === "Active" || record.status === "Expired"); const trial = item.status === "TrialActive" && item.activatedAt ? new Date(new Date(item.activatedAt).getTime() + 7 * 86400000).toISOString() : null; return <div key={item.id} className="rounded-lg border border-[#dae6e9] p-4"><div className="flex flex-wrap items-center justify-between gap-2"><strong>{item.name}</strong><span className="rounded-full bg-[#e7f1f2] px-2 py-1 text-xs font-bold">{item.status}</span></div><div className="mt-3 grid gap-3 sm:grid-cols-2">{trial ? <div className="rounded-lg bg-[#f3f7f8] p-3"><p className="text-xs font-bold uppercase text-slate-500">7-day trial</p><p className="mt-1 font-bold">{remaining(trial)} days remaining</p><p className="text-xs text-slate-500">Expires {new Date(trial).toLocaleDateString()}</p></div> : <div className="rounded-lg bg-[#f3f7f8] p-3 text-xs text-slate-500">No trial record.</div>}{subscription ? <div className="rounded-lg bg-[#f3f7f8] p-3"><p className="text-xs font-bold uppercase text-slate-500">365-day annual</p><p className="mt-1 font-bold">{remaining(subscription.expiresAt)} days remaining</p><p className="text-xs text-slate-500">{new Date(subscription.startedAt).toLocaleDateString()} – {new Date(subscription.expiresAt).toLocaleDateString()}</p></div> : <div className="rounded-lg bg-[#f3f7f8] p-3 text-xs text-slate-500">No annual subscription record.</div>}</div></div>; })}</div></Card>; }
function ActivityTimeline({ api }: { api: SuperAdminApi }) {
  const [activity, setActivity] = useState<SuperAdminActivity | null>(null);
  const [error, setError] = useState<{ message: string; expected: boolean } | null>(null);
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState("All");
  const [date, setDate] = useState("");
  const load = () => { setError(null); setActivity(null); void api.listActivity().then(setActivity).catch(reason => setError({ message: errorMessage(reason, "Unable to load activity."), expected: expectedUnavailable(reason) })); };
  useEffect(() => { load(); }, [api]);
  const describe = (log: SuperAdminAuditLog) => {
    const action = log.action.toLowerCase(); const company = log.company?.name;
    if (action.includes("trial") && action.includes("activ")) return company ? `Activated a 7-day trial for ${company}` : "Activated a 7-day trial";
    if (action.includes("annual") && action.includes("renew")) return company ? `Renewed the annual subscription for ${company}` : "Renewed an annual subscription";
    if (action.includes("annual") && action.includes("activ")) return company ? `Activated the annual subscription for ${company}` : "Activated an annual subscription";
    if (action.includes("referral") && action.includes("revoke")) return "Revoked a referral code";
    if (action.includes("referral")) return "Generated a referral code";
    if (action.includes("superadmin") && action.includes("revoke")) return "Revoked Superadmin access";
    if (action.includes("superadmin") && action.includes("creat")) return "Created a Superadmin account";
    if (action.includes("approv")) return company ? `Approved ${company}` : "Approved a company";
    if (action.includes("reject")) return company ? `Rejected ${company}` : "Rejected a company";
    if (action.includes("suspend")) return company ? `Suspended ${company}` : "Suspended a company";
    if (action.includes("membership") || action.includes("user")) return company ? `Changed company access for ${company}` : "Changed company access";
    return log.action.replace(/[._-]+/g, " ").replace(/\b\w/g, letter => letter.toUpperCase());
  };
  const categoryFor = (log: SuperAdminAuditLog) => { const a = log.action.toLowerCase(); if (a.includes("referral")) return "Referrals"; if (a.includes("subscription") || a.includes("trial") || a.includes("annual")) return "Subscriptions"; if (a.includes("superadmin")) return "Superadmins"; if (a.includes("company") || a.includes("membership") || a.includes("user")) return "Companies"; if (a.includes("security") || a.includes("csrf") || a.includes("authentication") || a.includes("login")) return "Security"; if (a.includes("notification")) return "Notifications"; return "Other"; };
  const tone = (log: SuperAdminAuditLog) => { const c = categoryFor(log); const styles: Record<string, { Icon: LucideIcon; icon: string; line: string; badge: string }> = { Companies: { Icon: Building2, icon: "text-cyan-700 bg-cyan-100 dark:bg-cyan-950/40", line: "bg-cyan-200 dark:bg-cyan-900", badge: c }, Subscriptions: { Icon: CalendarClock, icon: "text-teal-700 bg-teal-100 dark:bg-teal-950/40", line: "bg-teal-200 dark:bg-teal-900", badge: c }, Referrals: { Icon: KeyRound, icon: "text-amber-700 bg-amber-100 dark:bg-amber-950/40", line: "bg-amber-200 dark:bg-amber-900", badge: c }, Superadmins: { Icon: ShieldCheck, icon: "text-purple-700 bg-purple-100 dark:bg-purple-950/40", line: "bg-purple-200 dark:bg-purple-900", badge: c }, Security: { Icon: ShieldAlert, icon: "text-rose-700 bg-rose-100 dark:bg-rose-950/40", line: "bg-rose-200 dark:bg-rose-900", badge: c }, Notifications: { Icon: Bell, icon: "text-sky-700 bg-sky-100 dark:bg-sky-950/40", line: "bg-sky-200 dark:bg-sky-900", badge: c }, Other: { Icon: ActivityIcon, icon: "text-slate-600 bg-slate-100 dark:bg-slate-800", line: "bg-slate-200 dark:bg-slate-700", badge: c } }; return styles[c] || styles.Other; };
  const relative = (value: string) => { const seconds = Math.max(0, Math.floor((Date.now() - new Date(value).getTime()) / 1000)); if (seconds < 60) return "just now"; const minutes = Math.floor(seconds / 60); if (minutes < 60) return `${minutes} minute${minutes === 1 ? "" : "s"} ago`; const hours = Math.floor(minutes / 60); if (hours < 24) return `${hours} hour${hours === 1 ? "" : "s"} ago`; const days = Math.floor(hours / 24); return `${days} day${days === 1 ? "" : "s"} ago`; };
  const logs = (activity?.auditLogs || []).filter(log => { const c = categoryFor(log); const haystack = `${describe(log)} ${log.action} ${log.actor?.name || ""} ${log.actor?.email || ""} ${log.company?.name || ""}`.toLowerCase(); return (!query || haystack.includes(query.toLowerCase())) && (category === "All" || c === category) && (!date || log.createdAt.slice(0, 10) === date); }).sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  if (error) return <section className="space-y-5"><ActivityHeader /><Card title="Recent Activity"><div className="rounded-xl border border-rose-200 bg-rose-50 p-5 text-sm text-rose-800 dark:border-rose-900 dark:bg-rose-950/30 dark:text-rose-200">{error.message}<button type="button" onClick={load} className="ml-3 rounded-lg border border-rose-300 px-3 py-1.5 font-semibold">Retry</button></div></Card></section>;
  if (!activity) return <section className="space-y-5"><ActivityHeader /><Card title="Recent Activity"><div className="animate-pulse space-y-4 p-2"><div className="h-5 w-1/3 rounded bg-slate-200 dark:bg-slate-700" /><div className="h-16 rounded bg-slate-100 dark:bg-slate-800" /><div className="h-16 rounded bg-slate-100 dark:bg-slate-800" /></div></Card></section>;
  return <section className="space-y-5"><ActivityHeader /><Card title="Recent Activity"><div className="mb-5 flex flex-wrap items-center gap-2"><span className="rounded-full bg-[#e7f1f2] px-3 py-1.5 text-xs font-bold text-[#155e64] dark:bg-slate-800 dark:text-cyan-200">{activity.auditLogs.length} events</span><button type="button" onClick={load} className="ml-auto inline-flex items-center gap-2 rounded-lg border border-[#cbdde0] px-3 py-2 text-xs font-semibold dark:border-slate-700"><RefreshCw size={14} />Refresh</button></div><p className="-mt-3 mb-4 text-xs text-slate-500">Verified administrative events, newest first.</p><div className="mb-5 flex flex-wrap gap-2"><label className="flex min-w-[220px] flex-1 items-center gap-2 rounded-lg border border-[#cbdde0] bg-white px-3 dark:border-slate-700 dark:bg-slate-900"><Search size={14} className="text-slate-400" /><input aria-label="Search activities" value={query} onChange={event => setQuery(event.target.value)} placeholder="Search activities" className="h-9 min-w-0 flex-1 bg-transparent text-xs outline-none" /></label><select aria-label="Activity category" value={category} onChange={event => setCategory(event.target.value)} className="rounded-lg border border-[#cbdde0] bg-white px-3 text-xs dark:border-slate-700 dark:bg-slate-900">{["All", "Companies", "Subscriptions", "Referrals", "Superadmins", "Security", "Notifications", "Other"].map(item => <option key={item}>{item}</option>)}</select><input aria-label="Activity date" type="date" value={date} onChange={event => setDate(event.target.value)} className="rounded-lg border border-[#cbdde0] bg-white px-3 text-xs dark:border-slate-700 dark:bg-slate-900" /></div>{!logs.length ? <div className="rounded-xl border border-dashed border-[#cbdde0] p-8 text-center text-sm text-slate-500">{activity.auditLogs.length ? "No activities match the current filters." : "No persisted administrative audit records were returned."}</div> : <div className="space-y-0">{logs.map((log, index) => { const colors = tone(log); const Icon = colors.Icon; return <article key={log.id} className="relative flex gap-4 pb-6"><div className="relative flex w-8 shrink-0 justify-center"><span className={`z-10 flex h-8 w-8 items-center justify-center rounded-full ${colors.icon}`}><Icon size={15} /></span>{index < logs.length - 1 ? <span className={`absolute top-8 h-full w-px ${colors.line}`} /> : null}</div><div className="min-w-0 flex-1 rounded-xl border border-[#e2ecee] bg-[#fbfdfd] p-4 dark:border-slate-800 dark:bg-slate-900/60"><div className="flex flex-wrap items-start justify-between gap-2"><p className="font-semibold text-[#243b4a] dark:text-white">{describe(log)}</p><span className="rounded-full bg-slate-100 px-2 py-1 text-[10px] font-bold text-slate-600 dark:bg-slate-800 dark:text-slate-300">{colors.badge}</span></div><p className="mt-1 text-xs text-slate-500">{new Date(log.createdAt).toLocaleString()} · {relative(log.createdAt)}</p>{log.actor ? <p className="mt-2 text-xs text-slate-600 dark:text-slate-300">Actor: {log.actor.name} · {log.actor.email}</p> : <p className="mt-2 text-xs text-slate-500">Actor unavailable</p>}{log.company?.name ? <p className="mt-1 text-xs text-slate-500">Company: {log.company.name}</p> : null}</div></article>; })}</div>}</Card>{activity.notifications.length ? <Card title="Notification Delivery History"><p className="mb-4 text-xs text-slate-500">Delivery records are shown separately and are not administrative actions.</p><div className="overflow-x-auto"><table className="w-full min-w-[650px] text-left text-xs"><thead className="border-b border-[#d8e5e8] text-slate-500"><tr><th className="p-3">Type</th><th className="p-3">Recipient</th><th className="p-3">Scheduled</th><th className="p-3">Delivery status</th></tr></thead><tbody>{activity.notifications.map(item => <tr key={item.id} className="border-b border-[#eef3f4] dark:border-slate-800"><td className="p-3">{item.type}</td><td className="p-3">{item.recipient}</td><td className="p-3">{new Date(item.scheduledFor).toLocaleString()}</td><td className="p-3">{item.status}</td></tr>)}</tbody></table></div></Card> : null}</section>;
}
function ActivityHeader() { return <header><h2 className="flex items-center gap-2 text-[22px] font-bold text-[#123441] dark:text-white"><ActivityIcon size={21} className="text-teal-600" />Activity History</h2><p className="mt-1 text-[13px] text-slate-500 dark:text-slate-400">Auditable history of administrative actions.</p></header>; }
function Activity({ api }: { api: SuperAdminApi }) { return <ActivityTimeline api={api} />; }

type ClockRecord = { id: string; companyId: string; companyName: string; type: "Trial" | "Annual"; startedAt: string; expiresAt: string; status: "Trial" | "Active" | "Expiring Soon" | "Expired"; daysRemaining: number; elapsedDays: number; progress: number; canRenew: boolean };

function ClocksRedesignLegacy({ companies, details, detailErrors, api, onAction }: { companies: SuperAdminCompany[]; details: Record<string, CompanyDetail>; detailErrors: Record<string, string>; api: SuperAdminApi; onAction: (operation: () => Promise<SuperAdminCompany>) => Promise<void> }) {
  const [view, setView] = useState<"chart" | "table">("chart");
  const [query, setQuery] = useState("");
  const [type, setType] = useState("All");
  const [status, setStatus] = useState("All");
  const now = Date.now();
  const records: ClockRecord[] = companies.flatMap(company => {
    const detail = details[company.id];
    if (!detail) return [];
    return (["Trial", "Annual"] as const).flatMap(kind => {
      const subscription = detail.subscriptions.filter(item => kind === "Trial" ? item.status === "Trial" : item.status === "Active" || item.status === "Expired").sort((a, b) => new Date(b.expiresAt).getTime() - new Date(a.expiresAt).getTime() || new Date(b.startedAt).getTime() - new Date(a.startedAt).getTime())[0];
      if (!subscription) return [];
      const started = new Date(subscription.startedAt).getTime();
      const expires = new Date(subscription.expiresAt).getTime();
      const duration = Math.max(1, expires - started);
      const days = kind === "Trial" ? 7 : 365;
      const daysRemaining = Math.max(0, Math.ceil((expires - now) / 86400000));
      const elapsedDays = Math.max(0, Math.min(days, Math.ceil((now - started) / 86400000)));
      const expired = expires <= now;
      const recordStatus = expired ? "Expired" : kind === "Trial" ? "Trial" : kind === "Annual" && daysRemaining <= 30 ? "Expiring Soon" : "Active";
      return [{ id: subscription.id, companyId: company.id, companyName: company.name, type: kind, startedAt: subscription.startedAt, expiresAt: subscription.expiresAt, status: recordStatus, daysRemaining, elapsedDays, progress: Math.min(100, Math.max(0, ((now - started) / duration) * 100)), canRenew: kind === "Annual" }] as ClockRecord[];
    });
  });
  const visible = records.filter(item => (type === "All" || item.type === type) && (status === "All" || item.status === status) && item.companyName.toLowerCase().includes(query.toLowerCase()));
  const failedCompanies = companies.filter(company => detailErrors[company.id]);
  const annual = records.filter(item => item.type === "Annual");
  const tone = (value: ClockRecord["status"]) => value === "Active" ? "border-emerald-200 bg-emerald-50 text-emerald-700 dark:border-emerald-900 dark:bg-emerald-950/30 dark:text-emerald-300" : value === "Trial" ? "border-teal-200 bg-teal-50 text-teal-700 dark:border-teal-900 dark:bg-teal-950/30 dark:text-teal-300" : value === "Expiring Soon" ? "border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-900 dark:bg-amber-950/30 dark:text-amber-300" : "border-rose-200 bg-rose-50 text-rose-700 dark:border-rose-900 dark:bg-rose-950/30 dark:text-rose-300";
  const progressTone = (item: ClockRecord) => item.status === "Expired" ? "bg-rose-500" : item.status === "Expiring Soon" ? "bg-amber-500" : item.status === "Active" ? "bg-emerald-500" : "bg-teal-600";
  const ringTone = (value: ClockRecord["status"]) => value === "Expired" ? "text-rose-500" : value === "Expiring Soon" ? "text-amber-500" : value === "Active" ? "text-emerald-500" : "text-teal-600";
  const progress = (item: ClockRecord) => <div className="mt-2 h-2 rounded-full bg-slate-100 dark:bg-slate-700"><div className={`h-full rounded-full ${progressTone(item)}`} style={{ width: item.progress + "%" }} /></div>;
  const renew = (item: ClockRecord) => { if (!window.confirm(`${item.status === "Expired" ? "Renew" : "Extend"} the annual subscription for ${item.companyName}?`)) return; void onAction(() => api.renewAnnual(item.companyId, { pipelineKmLimit: Number(details[item.companyId]?.subscriptions[0]?.pipelineKmLimit || 0), namedUserLimit: Number(details[item.companyId]?.subscriptions[0]?.namedUserLimit || 0) })); };
  return <section className="space-y-5"><header className="flex flex-wrap items-end justify-between gap-3"><div><h2 className="flex items-center gap-2 text-[22px] font-bold text-[#123441] dark:text-white"><Clock3 size={20} className="text-teal-600" />365-Day Subscription Clocks</h2><p className="mt-1 text-[13px] text-slate-500 dark:text-slate-400">Persisted trial and annual cycles measured from their saved activation timestamps.</p></div><div className="rounded-lg border border-[#cbdde0] bg-white p-1 text-[12px] dark:border-slate-700 dark:bg-slate-900"><button type="button" onClick={() => setView("chart")} className={view === "chart" ? "rounded-md bg-[#087e7c] px-3 py-1.5 font-semibold text-white" : "px-3 py-1.5 text-slate-500"}>Chart View</button><button type="button" onClick={() => setView("table")} className={view === "table" ? "rounded-md bg-[#087e7c] px-3 py-1.5 font-semibold text-white" : "px-3 py-1.5 text-slate-500"}>Table View</button></div></header><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{[["Healthy", annual.filter(item => item.status !== "Expired" && item.daysRemaining > 90).length, "More than 90 days"], ["Renewal Window", annual.filter(item => item.status !== "Expired" && item.daysRemaining >= 31 && item.daysRemaining <= 90).length, "31–90 days"], ["Urgent / Expired", annual.filter(item => item.status === "Expired" || item.daysRemaining <= 30).length, "30 days or fewer"], ["Trials", records.filter(item => item.type === "Trial").length, "Persisted trial clocks"]].map(([label, value, detail]) => <div key={String(label)} className="rounded-xl border border-[#d8e5e8] bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-[#102830]"><p className="text-[11px] font-bold uppercase text-slate-500">{label}</p><strong className="mt-1 block text-2xl text-[#087e7c]">{value}</strong><p className="text-[12px] text-slate-500">{detail}</p></div>)}</div><div className="flex flex-wrap gap-2"><input aria-label="Search subscription clocks" value={query} onChange={event => setQuery(event.target.value)} placeholder="Search companies..." className="h-10 min-w-[220px] flex-1 rounded-lg border border-[#cbdde0] bg-white px-3 text-[13px] dark:border-slate-700 dark:bg-slate-900" /><select value={type} onChange={event => setType(event.target.value)} className="h-10 rounded-lg border border-[#cbdde0] bg-white px-3 text-[13px] dark:border-slate-700 dark:bg-slate-900"><option>All</option><option>Trial</option><option>Annual</option></select><select value={status} onChange={event => setStatus(event.target.value)} className="h-10 rounded-lg border border-[#cbdde0] bg-white px-3 text-[13px] dark:border-slate-700 dark:bg-slate-900"><option>All</option><option>Trial</option><option>Active</option><option>Expiring Soon</option><option>Expired</option></select></div>{view === "chart" ? <div className="grid gap-4 md:grid-cols-2">{visible.map(item => <article key={item.id} className="rounded-2xl border border-[#d8e5e8] bg-white p-4 shadow-sm dark:border-slate-800 dark:bg-[#102830]"><div className="flex items-start justify-between gap-3"><div><h3 className="font-bold text-[#123441] dark:text-white">{item.companyName}</h3><p className="text-[12px] text-slate-500">{item.type} subscription</p></div><span className={`rounded-full border px-2 py-1 text-[11px] font-semibold ${tone(item.status)}`}>{item.status}</span></div><div className="mt-4 flex items-center gap-4"><div className="relative h-28 w-28 shrink-0"><svg viewBox="0 0 100 100" className="-rotate-90"><circle cx="50" cy="50" r="42" fill="none" stroke="currentColor" strokeWidth="8" className="text-slate-100 dark:text-slate-700" /><circle cx="50" cy="50" r="42" fill="none" stroke="currentColor" strokeWidth="8" strokeLinecap="round" strokeDasharray={264} strokeDashoffset={264 - 264 * item.progress / 100} className="text-teal-600" /></svg><div className="absolute inset-0 flex flex-col items-center justify-center"><strong className="text-xl dark:text-white">{item.daysRemaining}</strong><span className="text-[10px] uppercase text-slate-500">days left</span></div></div><div className="text-[12px] text-slate-500"><p><strong>Activated:</strong> {new Date(item.startedAt).toLocaleDateString()}</p><p className="mt-2"><strong>Expires:</strong> {new Date(item.expiresAt).toLocaleDateString()}</p><p className="mt-2">{item.elapsedDays} elapsed days of {item.type === "Trial" ? 7 : 365}</p>{progress(item)}</div></div><div className="mt-4 flex justify-end border-t border-[#eef3f4] pt-3">{item.canRenew ? <button type="button" onClick={() => renew(item)} className="rounded-lg border border-teal-200 px-3 py-2 text-[12px] font-semibold text-teal-700">Renew 365 days</button> : <span className="text-[12px] text-slate-400">{item.type === "Trial" ? "Annual activation follows trial expiry" : "No renewal action available"}</span>}</div></article>)}</div> : <div className="overflow-x-auto rounded-2xl border border-[#d8e5e8] bg-white dark:border-slate-800 dark:bg-[#102830]"><table className="w-full min-w-[900px] text-left text-[12px]"><thead className="border-b border-[#d8e5e8] text-[11px] uppercase text-slate-500"><tr><th className="px-4 py-3">Company</th><th className="px-3 py-3">Type</th><th className="px-3 py-3">Activated</th><th className="px-3 py-3">Expires</th><th className="px-3 py-3">Days</th><th className="px-3 py-3">Progress</th><th className="px-3 py-3">Status</th><th className="px-3 py-3">Actions</th></tr></thead><tbody>{visible.map(item => <tr key={item.id} className="border-b border-[#eef3f4] dark:border-slate-800"><td className="px-4 py-3 font-semibold dark:text-white">{item.companyName}</td><td className="px-3 py-3">{item.type}</td><td className="px-3 py-3">{new Date(item.startedAt).toLocaleDateString()}</td><td className="px-3 py-3">{new Date(item.expiresAt).toLocaleDateString()}</td><td className="px-3 py-3 font-semibold">{item.daysRemaining}</td><td className="min-w-[150px] px-3 py-3">{progress(item)}</td><td className="px-3 py-3"><span className={`rounded-full border px-2 py-1 text-[11px] font-semibold ${tone(item.status)}`}>{item.status}</span></td><td className="px-3 py-3">{item.canRenew ? <button type="button" onClick={() => renew(item)} className="rounded-lg border border-teal-200 px-3 py-1.5 text-[12px] font-semibold text-teal-700">Renew</button> : <span className="text-slate-400">—</span>}</td></tr>)}</tbody></table></div>}{!visible.length ? <div className="rounded-xl border border-dashed border-[#cbdde0] p-8 text-center text-[13px] text-slate-500">{records.length ? "No subscription clocks match the current filters." : "No persisted trial or annual subscription records are available."}</div> : null}</section>;
}

function ProtectedNote({ api = superAdminApi }: { api?: SuperAdminApi }) {
  return <SuperadminAccessView api={api} />;
}

function SuperadminRegistry({ api }: { api: SuperAdminApi }) {
  const [registry, setRegistry] = useState<SuperAdminRegistryEntry[] | null>(null);
  const [registryError, setRegistryError] = useState<string | null>(null);
  const [busyId, setBusyId] = useState<string | null>(null);
  const [status, setStatus] = useState<{ kind: "error" | "success"; message: string } | null>(null);

  useEffect(() => {
    let active = true;
    void api.listSuperadmins().then((items) => {
      if (active) setRegistry(items);
    }).catch((reason) => {
      if (active) setRegistryError(errorMessage(reason, "Unable to load Superadmin registry."));
    });
    return () => { active = false; };
  }, [api]);

  if (registryError) return <p className="p-5 text-[13px] text-rose-700 dark:text-rose-300">{registryError}</p>;
  if (!registry) return <p className="p-5 text-[13px] text-slate-500 dark:text-slate-400">Loading registered Superadmins…</p>;
  if (!registry.length) return <p className="p-5 text-[13px] text-slate-500 dark:text-slate-400">No persisted Superadmin accounts found.</p>;

  async function revoke(entry: SuperAdminRegistryEntry) { if (!window.confirm(`Revoke Superadmin access for ${entry.user.email}?`)) return; setBusyId(entry.id); setStatus(null); try { await api.revokeSuperadmin(entry.id); setStatus({ kind: "success", message: `Access revoked for ${entry.user.email}.` }); const items = await api.listSuperadmins(); setRegistry(items); } catch (reason) { setStatus({ kind: "error", message: errorMessage(reason, "Unable to revoke Superadmin access.") }); } finally { setBusyId(null); } }
  return <div className="overflow-x-auto"><table className="w-full min-w-[820px] text-left text-[13px]"><thead className="border-b border-[#eef3f4] text-[11px] uppercase tracking-wide text-slate-500 dark:border-slate-800"><tr><th className="px-5 py-3">Operator</th><th className="px-5 py-3">Email</th><th className="px-5 py-3">Authority</th><th className="px-5 py-3">Source</th><th className="px-5 py-3">Registered</th><th className="px-5 py-3">Actions</th></tr></thead><tbody>{registry.map((entry) => <tr key={entry.id} className="border-b border-[#eef3f4] last:border-0 dark:border-slate-800"><td className="px-5 py-3 font-semibold text-[#243b4a] dark:text-white">{entry.user.name}</td><td className="px-5 py-3 text-slate-600 dark:text-slate-300">{entry.user.email}</td><td className="px-5 py-3"><span className={`rounded-full px-2 py-1 text-[11px] font-semibold ${entry.status === "Active" ? "bg-emerald-50 text-emerald-700 dark:bg-emerald-950/40 dark:text-emerald-300" : "bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-300"}`}>{entry.status}</span></td><td className="px-5 py-3 text-slate-500 dark:text-slate-400">{entry.source}</td><td className="px-5 py-3 text-slate-500 dark:text-slate-400">{new Date(entry.createdAt).toLocaleDateString()}</td><td className="px-5 py-3">{entry.source === "Database" && entry.status === "Active" ? <button type="button" disabled={busyId !== null} onClick={() => void revoke(entry)} className="rounded-lg bg-rose-600 px-3 py-2 text-[11px] font-bold text-white disabled:cursor-not-allowed disabled:opacity-50">{busyId === entry.id ? "Revoking…" : "Revoke Access"}</button> : <span className="text-xs text-slate-400">—</span>}</td></tr>)}</tbody></table>{status ? <p role="status" className={`p-5 text-[12px] ${status.kind === "success" ? "text-emerald-700 dark:text-emerald-300" : "text-rose-700 dark:text-rose-300"}`}>{status.message}</p> : null}</div>;
}

function GrantSuperadminForm({ api, onCreated }: { api: SuperAdminApi; onCreated: () => void }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [status, setStatus] = useState<{ kind: "error" | "success"; message: string } | null>(null);
  const [busy, setBusy] = useState(false);
  async function submit(event: React.FormEvent) {
    event.preventDefault(); setStatus(null);
    if (!/^\S+@\S+\.\S+$/.test(email.trim())) { setStatus({ kind: "error", message: "Enter a valid operator email." }); return; }
    if (password !== confirmPassword) { setStatus({ kind: "error", message: "Passwords do not match." }); return; }
    if (!window.confirm("Grant Superadmin access to this operator?")) return;
    setBusy(true);
    try { await api.createSuperadmin({ email: email.trim(), password }); setEmail(""); setPassword(""); setConfirmPassword(""); setStatus({ kind: "success", message: "Superadmin access granted." }); onCreated(); } catch (reason) { setStatus({ kind: "error", message: errorMessage(reason, "Unable to grant Superadmin access.") }); } finally { setBusy(false); }
  }
  return <form onSubmit={submit} className="space-y-4 p-5"><div><label className="text-[11px] font-bold uppercase tracking-wide text-slate-500" htmlFor="superadmin-email">Operator email</label><input id="superadmin-email" value={email} onChange={event => setEmail(event.target.value)} type="email" required autoComplete="off" className="mt-2 h-10 w-full rounded-lg border border-[#cbdde0] bg-white px-3 text-[13px] dark:border-slate-700 dark:bg-slate-800 dark:text-white" /></div><div><label className="text-[11px] font-bold uppercase tracking-wide text-slate-500" htmlFor="superadmin-password">Password</label><div className="mt-2 flex gap-2"><input id="superadmin-password" value={password} onChange={event => setPassword(event.target.value)} type={showPassword ? "text" : "password"} required minLength={12} autoComplete="new-password" className="h-10 min-w-0 flex-1 rounded-lg border border-[#cbdde0] bg-white px-3 text-[13px] dark:border-slate-700 dark:bg-slate-800 dark:text-white" /><button type="button" onClick={() => setShowPassword(value => !value)} className="rounded-lg border px-3 text-[12px] text-slate-600 dark:border-slate-700 dark:text-slate-300">{showPassword ? "Hide" : "Show"}</button></div></div><div><label className="text-[11px] font-bold uppercase tracking-wide text-slate-500" htmlFor="superadmin-confirm-password">Confirm password</label><input id="superadmin-confirm-password" value={confirmPassword} onChange={event => setConfirmPassword(event.target.value)} type={showPassword ? "text" : "password"} required minLength={12} autoComplete="new-password" className="mt-2 h-10 w-full rounded-lg border border-[#cbdde0] bg-white px-3 text-[13px] dark:border-slate-700 dark:bg-slate-800 dark:text-white" /></div><p className="text-[12px] text-slate-500 dark:text-slate-400">Use at least 12 characters with upper/lowercase letters, a number and a symbol. OTP verification remains required at login.</p><button type="submit" disabled={busy} className="rounded-lg bg-[#087e7c] px-4 py-2.5 text-[12px] font-bold text-white disabled:opacity-50">{busy ? "Granting…" : "Grant access"}</button>{status ? <p role="status" className={`text-[12px] ${status.kind === "success" ? "text-emerald-700 dark:text-emerald-300" : "text-rose-700 dark:text-rose-300"}`}>{status.message}</p> : null}</form>;
}

function SuperadminAccessView({ api }: { api: SuperAdminApi }) {
  const [refreshKey, setRefreshKey] = useState(0);
  return <section className="space-y-5">
    <header className="flex flex-wrap items-end justify-between gap-3"><div><h2 className="flex items-center gap-2 text-[22px] font-bold text-[#123441] dark:text-white"><ShieldCheck size={21} className="text-teal-600" />Superadmin Access</h2><p className="mt-1 text-[13px] text-slate-500 dark:text-slate-400">Console-level operators with cross-client privileges.</p></div><span className="inline-flex items-center gap-2 rounded-full border border-emerald-200 bg-emerald-50 px-3 py-1.5 text-[12px] font-semibold text-emerald-700 dark:border-emerald-900 dark:bg-emerald-950/30 dark:text-emerald-300"><span className="h-2 w-2 rounded-full bg-emerald-500" />Database connected</span></header>
    <div className="grid gap-5 lg:grid-cols-[1.35fr_0.65fr]"><section className="rounded-2xl border border-[#d8e5e8] bg-white shadow-sm dark:border-slate-800 dark:bg-[#102830]"><div className="border-b border-[#eef3f4] p-5 dark:border-slate-800"><h3 className="flex items-center gap-2 text-[16px] font-bold text-[#123441] dark:text-white"><LockKeyhole size={17} className="text-teal-600" />Grant Superadmin Access</h3><p className="mt-1 text-[13px] text-slate-500">Create a database-backed operator account. OTP verification remains part of the shared login.</p></div><GrantSuperadminForm api={api} onCreated={() => setRefreshKey(value => value + 1)} /></section><section className="rounded-2xl border border-teal-200 bg-teal-50 p-5 shadow-sm dark:border-teal-900 dark:bg-teal-950/30"><h3 className="flex items-center gap-2 text-[13px] font-bold uppercase tracking-wide text-teal-700 dark:text-teal-300"><UsersRound size={16} />Total Superadmins</h3><SuperadminCount key={refreshKey} api={api} /></section></div>
    <section className="overflow-hidden rounded-2xl border border-[#d8e5e8] bg-white shadow-sm dark:border-slate-800 dark:bg-[#102830]"><div className="border-b border-[#eef3f4] p-5 dark:border-slate-800"><h3 className="flex items-center gap-2 text-[16px] font-bold text-[#123441] dark:text-white"><UsersRound size={17} className="text-teal-600" />Superadmin Registry</h3><p className="mt-1 text-[13px] text-slate-500">Persisted and configured platform accounts only. Sessions and company admins are excluded.</p></div><SuperadminRegistry key={refreshKey} api={api} /></section>
  </section>;
}

function SuperadminCount({ api }: { api: SuperAdminApi }) {
  const [count, setCount] = useState<number | null>(null);
  useEffect(() => { let active = true; void api.listSuperadmins().then(items => { if (active) setCount(items.length); }); return () => { active = false; }; }, [api]);
  return <><strong className="mt-3 block text-5xl font-bold text-[#087e7c] dark:text-teal-300">{count === null ? "—" : count}</strong><p className="mt-2 text-[13px] text-teal-800/75 dark:text-teal-200/75">Registered Superadmin accounts only; active sessions are not counted.</p></>;
}

export default function SuperAdminManagePage() {
  const router = useRouter();
  const [api] = useState<SuperAdminApi>(() => demoMode ? createSuperAdminMockApi() : superAdminApi);
  const [tab, setTab] = useState<Tab>("dashboard");
  const [companies, setCompanies] = useState<SuperAdminCompany[]>([]);
  const [details, setDetails] = useState<Record<string, CompanyDetail>>({});
  const [detailErrors, setDetailErrors] = useState<Record<string, string>>({});
  const [configuration, setConfiguration] = useState<SuperAdminConfiguration | null>(null);
  const [activity, setActivity] = useState<SuperAdminActivity | null>(null);
  const [selectedId, setSelectedId] = useState("");
  const [legacy, setLegacy] = useState<LegacySuperAdminData | null>(null);
  const [error, setError] = useState<{ message: string; expected: boolean } | null>(null);
  const [loading, setLoading] = useState(true);
  const selected = useMemo(() => companies.find(item => item.id === selectedId), [companies, selectedId]);
  async function refresh() { setError(null); setLoading(true); try { const [companyResult, configResult, legacyResult, activityResult] = await Promise.allSettled([api.listCompanies(), api.getConfiguration(), api.getLegacyData(), api.listActivity()]); const failures: unknown[] = []; if (companyResult.status === "fulfilled") { const items = companyResult.value; const detailResults = await Promise.allSettled(items.map(item => api.getCompany(item.id))); const nextDetails: Record<string, CompanyDetail> = {}; const nextDetailErrors: Record<string, string> = {}; detailResults.forEach((result, index) => { const company = items[index]; if (result.status === "fulfilled") nextDetails[company.id] = result.value; else { nextDetailErrors[company.id] = errorMessage(result.reason, "Unable to load company details."); failures.push(result.reason); } }); setCompanies(items); setDetails(nextDetails); setDetailErrors(nextDetailErrors); setSelectedId(current => current && items.some(item => item.id === current) ? current : items[0]?.id || ""); } else failures.push(companyResult.reason); if (configResult.status === "fulfilled") setConfiguration(configResult.value); else failures.push(configResult.reason); if (legacyResult.status === "fulfilled") setLegacy(legacyResult.value); else failures.push(legacyResult.reason); if (activityResult.status === "fulfilled") setActivity(activityResult.value); else failures.push(activityResult.reason); const failed = failures[0]; if (failed) setError({ message: errorMessage(failed, "Unable to load Super Admin data."), expected: expectedUnavailable(failed) }); } catch (reason) { setError({ message: errorMessage(reason, "Unable to load Super Admin data."), expected: expectedUnavailable(reason) }); } finally { setLoading(false); } }
  useEffect(() => { if (demoMode) { void refresh(); return; } fetch(`${(process.env.NEXT_PUBLIC_API_BASE_URL || "http://localhost:4002").replace(/\/$/, "")}/api/super-admin-auth/session`, { credentials: "include" }).then(response => { if (!response.ok) router.replace("/super-admin/login"); else void refresh(); }).catch(() => router.replace("/super-admin/login")); }, [api, router]);
  async function action(operation: () => Promise<SuperAdminCompany>) { try { await operation(); await refresh(); } catch (reason) { setError({ message: errorMessage(reason, "Super Admin operation failed."), expected: expectedUnavailable(reason) }); } }
  if (loading) return <main className="p-8 text-sm">Loading protected Super Admin data</main>;
return <main className="min-h-screen bg-[#eef5f6] text-[#15313d] dark:bg-[#07171d] dark:text-slate-100"><header className="relative overflow-hidden bg-[#123441] px-5 py-5 text-white shadow-lg sm:px-8"><div className="relative mx-auto flex max-w-none items-center justify-between gap-5"><div className="flex min-w-0 items-center gap-4"><div className="flex h-12 w-12 shrink-0 items-center justify-center overflow-hidden rounded-xl bg-white p-1 shadow-md"><img src="/klinthru-logo.png" alt="Klinthru" className="h-full w-full object-contain" /></div><div className="min-w-0"><p className="text-[10px] font-bold uppercase tracking-[0.2em] text-[#9bd9d4]">Pipeline integrity intelligence</p><h1 className="mt-1 truncate text-2xl font-bold tracking-tight">Super Admin</h1><p className="mt-1 text-[13px] text-cyan-100">Company, subscription and platform administration</p></div></div><div className="flex items-center gap-2"><span className="rounded-full border border-cyan-200/30 bg-white/10 px-3 py-1.5 text-[11px] font-bold uppercase tracking-wide">{demoMode ? "Isolated mock API" : "Protected API"}</span>{!demoMode ? <button type="button" onClick={() => { void fetch(`${(process.env.NEXT_PUBLIC_API_BASE_URL || "http://localhost:4002").replace(/\/$/, "")}/api/super-admin-auth/logout`, { method: "POST", credentials: "include" }).finally(() => router.replace("/super-admin/login")); }} className="rounded-lg border border-white/30 px-3 py-1.5 text-[11px] font-bold uppercase tracking-wide">Log out</button> : null}</div></div></header><nav className="sticky top-0 z-20 border-b border-[#d7e5e7] bg-white/95 px-4 py-3 shadow-sm backdrop-blur dark:border-slate-800 dark:bg-[#102830]/95 sm:px-6"><div className="mx-auto flex max-w-none gap-2 overflow-x-auto pb-0.5">{tabs.map(([key, label]) => <button key={key} type="button" onClick={() => setTab(key)} className={`whitespace-nowrap rounded-lg px-3.5 py-2.5 text-[13px] font-bold transition ${tab === key ? "bg-[#087e7c] text-white shadow-sm" : "bg-[#e7f1f2] text-[#164e56] hover:bg-[#d5e8e9] dark:bg-slate-800 dark:text-cyan-200"}`}>{label}</button>)}</div></nav><section className="w-full max-w-none space-y-5 px-4 py-5 sm:px-6 sm:py-6">{error ? <div role="status" className={`rounded-lg border p-3 text-sm shadow-sm ${error.expected ? "border-[#c8dfe1] bg-[#f3f7f8] text-[#155e64]" : "border-rose-200 bg-rose-50 text-rose-800"}`}>{error.expected ? "Company management will be available after database activation." : error.message}</div> : null}{tab === "dashboard" ? <DashboardView companies={companies} details={details} detailErrors={detailErrors} configuration={configuration} activity={activity} dataAvailable={!error && Object.keys(detailErrors).length === 0} legacy={legacy} onNavigate={setTab} /> : null}{tab === "referrals" ? <Referrals api={api} companies={companies} details={details} /> : null}{tab === "clients" ? <><Clients api={api} companies={companies} details={details} selected={selected} onSelect={setSelectedId} onAction={action} /></> : null}{tab === "clocks" ? <ClocksRedesign companies={companies} details={details} detailErrors={detailErrors} api={api} onAction={action} /> : null}{tab === "superadmin" ? <ProtectedNote /> : null}{tab === "activity" ? <Activity api={api} /> : null}</section></main>;
}
